  /**
   * Calculates the Hidden Gem Score (weighted average of sub-scores)
   */
  function calculateHiddenGemScore(reviews) {
    if (!reviews || reviews.length === 0) {
      return {
        overallScore: 0,
        foodQuality: 0,
        priceWorth: 0,
        service: 0,
        ambience: 0,
        consistency: 0,
        reviewCount: 0
      };
    }
    var foodTotal = 0;
    var priceTotal = 0;
    var serviceTotal = 0;
    var ambienceTotal = 0;
    var consistencyTotal = 0;
    for (var r of reviews) {
      foodTotal += r.food_quality;
      priceTotal += r.price_worth;
      serviceTotal += r.service;
      ambienceTotal += r.ambience;
      consistencyTotal += r.consistency;
    }
    var count = reviews.length;
    var foodQuality = foodTotal / count;
    var priceWorth = priceTotal / count;
    var service = serviceTotal / count;
    var ambience = ambienceTotal / count;
    var consistency = consistencyTotal / count;
    // Weighted calculation: Food Quality (40%), Price Worth (25%), Consistency (15%), Service (10%), Ambience (10%)
    var rawWeighted = foodQuality * 0.4 + priceWorth * 0.25 + consistency * 0.15 + service * 0.1 + ambience * 0.1;
    // Scale to 10-point scale
    var overallScore = Math.round(rawWeighted * 2 * 10) / 10;
    return {
      overallScore: overallScore,
      foodQuality: Math.round(foodQuality * 10) / 10,
      priceWorth: Math.round(priceWorth * 10) / 10,
      service: Math.round(service * 10) / 10,
      ambience: Math.round(ambience * 10) / 10,
      consistency: Math.round(consistency * 10) / 10,
      reviewCount: count
    };
  }
